void lock(Route r) {
  r.state = 'LOCKED';
  r.passed.clear();
  for (final s in r.sections) {
    s.route = r;
  }
  for (final s in r.overlap) {
    s.overlaps.add(r);
  }
  for (final requirement in r.requirements()) {
    requirement.point.locks.add(PointLock(r, requirement.position));
  }
  r.overlapLocked = true;
  r.overlapCounter = 0;
  r.releaseTime = -1;
}
